svg.script:
(function () {
  const map = document.documentElement;
  const tooltip = document.getElementById('map-tooltip');
  const tooltipName = document.getElementById('tooltip-name');
  const tooltipWidth = 250;
  const tooltipHeight = 90;

  function getProvince(target) {
    return target && target.closest ? target.closest('.province') : null;
  }

  function mapPoint(event) {
    // Convierte las coordenadas del cursor al sistema escalable del SVG.
    const point = map.createSVGPoint();
    point.x = event.clientX;
    point.y = event.clientY;
    return point.matrixTransform(map.getScreenCTM().inverse());
  }

  function showTooltip(province, point) {
    if (!province) return;

    const bounds = map.viewBox.baseVal;
    const margin = 12;
    let x = point.x + 18;
    let y = point.y + 18;

    if (x + tooltipWidth > bounds.x + bounds.width - margin) {
      x = point.x - tooltipWidth - 18;
    }
    if (y + tooltipHeight > bounds.y + bounds.height - margin) {
      y = point.y - tooltipHeight - 18;
    }

    x = Math.max(bounds.x + margin, Math.min(x, bounds.x + bounds.width - tooltipWidth - margin));
    y = Math.max(bounds.y + margin, Math.min(y, bounds.y + bounds.height - tooltipHeight - margin));
    tooltipName.textContent = province.getAttribute('data-provincia');
    tooltip.setAttribute('transform', 'translate(' + x + ' ' + y + ')');
    tooltip.setAttribute('visibility', 'visible');
  }

  function hideTooltip() {
    tooltip.setAttribute('visibility', 'hidden');
  }

  map.addEventListener('mouseover', function (event) {
    const province = getProvince(event.target);
    if (province) showTooltip(province, mapPoint(event));
  });

  map.addEventListener('mousemove', function (event) {
    const province = getProvince(event.target);
    if (province) showTooltip(province, mapPoint(event));
  });

  map.addEventListener('mouseout', function (event) {
    if (getProvince(event.target) && !getProvince(event.relatedTarget)) hideTooltip();
  });

  map.addEventListener('focusin', function (event) {
    const province = getProvince(event.target);
    if (!province) return;
    const bounds = province.getBBox();
    showTooltip(province, { x: bounds.x + bounds.width / 2, y: bounds.y + bounds.height / 2 });
  });

  map.addEventListener('focusout', function (event) {
    if (getProvince(event.target) && !getProvince(event.relatedTarget)) hideTooltip();
  });

  map.addEventListener('click', function (event) {
    const province = getProvince(event.target);
    if (province) showTooltip(province, mapPoint(event));
  });

  map.addEventListener('keydown', function (event) {
    const province = getProvince(event.target);
    if (event.key === 'Escape') hideTooltip();
    if (province && (event.key === 'Enter' || event.key === ' ')) {
      event.preventDefault();
      const bounds = province.getBBox();
      showTooltip(province, { x: bounds.x + bounds.width / 2, y: bounds.y + bounds.height / 2 });
    }
  });
})();
